algorithms.pseudocode:
function ExtractWitness(c1, s1, c2, s2, p):
    assert c1 != c2          # forking condition
    delta <- (c1 - c2) mod p
    delta_inv <- ModInverse(delta, p)   # exists since p prime, delta != 0
    x_star <- (delta_inv * (s1 - s2)) mod p
    return x_star            # guarantees x_star * g == Y (mod p)

